scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_ReportDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.goAction(r["formCd"], r["formVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "0", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["byformUsrTpCd"], r["exmptObjDisclsYn"], r["ismulti"], r["editClssCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};

